/**
 * One icon per puzzle theme for the themes page, painted the way the variant
 * markers are: a white-on-transparent PNG used as a CSS mask over
 * `currentColor` (`.variant-marker` in variant-markers.css), so an icon takes
 * the row's text colour in light and dark and on the recommended row's tint.
 *
 * The art is generated by an image model with the variant markers as style
 * references (Brian, 2026-10-29, after rejecting hand-written SVG scenes as
 * "SVG slop"), 256x256 masks under apps/web/public/puzzle-theme-icons/, named
 * by theme id. A theme with no art (the rare mate patterns, under the page's
 * 20-puzzle floor) wears its group's line icon below; theme-icons.test.ts
 * fails a path with no file on disk and a shown theme with no icon.
 */
import '../variant-markers.css';
import type { XiangqiTrainingTagGroup, XiangqiTrainingTagId } from '@mistboard/game';

export type ThemeIconKey = XiangqiTrainingTagId | 'mix';

const art = (id: ThemeIconKey) => `/puzzle-theme-icons/${id}.png`;

/** The themes that have generated art, by id, to their public path. */
export const THEME_ICON_PATH: Readonly<Partial<Record<ThemeIconKey, string>>> = {
  mix: art('mix'),
  // Mate patterns
  'bai-lian-jiang': art('bai-lian-jiang'),
  'chong-pao': art('chong-pao'),
  'diao-yu-ma': art('diao-yu-ma'),
  'ma-hou-pao': art('ma-hou-pao'),
  'shuang-ju-cuo': art('shuang-ju-cuo'),
  'shuang-zhao-jiang': art('shuang-zhao-jiang'),
  'tian-di-pao': art('tian-di-pao'),
  'tie-men-shuan': art('tie-men-shuan'),
  // Mate in N
  matein1: art('matein1'),
  matein2: art('matein2'),
  matein3: art('matein3'),
  matein4: art('matein4'),
  // Phases
  opening: art('opening'),
  middlegame: art('middlegame'),
  endgame: art('endgame'),
  // Goals
  checkmate: art('checkmate'),
  winning: art('winning'),
  // Lengths
  'one-move': art('one-move'),
  short: art('short'),
  long: art('long'),
  'very-long': art('very-long'),
};

const LINE =
  'fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"';

/*
 * The group icons: the fallback for a theme with no art of its own. Same
 * ring, same 5-unit round stroke, no text or hanzi.
 */
export const GROUP_ICON: Record<XiangqiTrainingTagGroup | 'mix', string> = {
  // Two crossing arrows: everything, shuffled.
  mix: `<path ${LINE} d="M28 39 H38 C51 39 49 61 62 61 H70 M28 61 H38 C51 61 49 39 62 39 H70 M64 33 L70 39 L64 45 M64 55 L70 61 L64 67"/>`,
  // The palace, its diagonals and the general caught at its centre.
  motif: `<path ${LINE} d="M32 32 H68 V68 H32 Z M32 32 L68 68 M68 32 L32 68"/><circle cx="50" cy="50" r="8" fill="currentColor"/>`,
  // A sight on the general: forced mate.
  mate: `<circle cx="50" cy="50" r="15" ${LINE}/><path ${LINE} d="M50 25 V35 M50 65 V75 M25 50 H35 M65 50 H75"/><circle cx="50" cy="50" r="5" fill="currentColor"/>`,
  // An hourglass: where the game is.
  phase: `<path ${LINE} d="M36 30 H64 M36 70 H64 M39 30 C39 45 61 53 61 70 M61 30 C61 45 39 53 39 70"/>`,
  // A flag on its pole: what the line wins.
  goal: `<path ${LINE} d="M37 72 V28 M37 31 C47 25 55 37 66 31 V51 C55 57 47 45 37 51"/>`,
  // Moves along a path to an arrow: how long the line is.
  length: `<path ${LINE} d="M29 63 L43 49 L56 58 L70 41 M60 40 H71 V51"/><circle cx="29" cy="63" r="4" fill="currentColor"/><circle cx="43" cy="49" r="4" fill="currentColor"/><circle cx="56" cy="58" r="4" fill="currentColor"/>`,
};

function groupIconSvg(group: XiangqiTrainingTagGroup | 'mix'): string {
  return `<svg viewBox="0 0 100 100" focusable="false"><circle cx="50" cy="50" r="46" fill="none" stroke="currentColor" stroke-width="2.5"/>${GROUP_ICON[group]}</svg>`;
}

/**
 * The icon's inner markup: the theme's art as a mask-painted marker, or its
 * group's line icon for a theme without art. `own` says which.
 */
export function themeIconMarkup(
  key: string,
  group: XiangqiTrainingTagGroup | 'mix',
): { markup: string; own: boolean } {
  const path = (THEME_ICON_PATH as Readonly<Record<string, string | undefined>>)[key];
  if (!path) return { markup: groupIconSvg(group), own: false };
  return {
    markup: `<span class="variant-marker" style="--variant-marker-mask: url('${path}')"></span>`,
    own: true,
  };
}
